insert into kairo.questions (id, subject, topic, subtopic, learning_objective, concepts_tested, difficulty_rating, cognitive_level, estimated_solving_time_sec, reading_load, calculation_load, distractors, source, year, exam_body, stem, options, correct_option, explanation, lifecycle_state, distractor_rationale) values
($q$chemistry_0245$q$, $q$Chemistry$q$, $q$Separation of Mixtures$q$, $q$Separation Techniques — Selective Solubility$q$, $q$Answer a real JAMB 2000 question on Separation Techniques — Selective Solubility.$q$, $q$[{"conceptId": "mt5suz", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Assumes sulphur is water-soluble because it's a familiar 'dissolve it in water' instinct — but elemental sulphur is a nonpolar covalent solid and essentially insoluble in water.", "misconceptionId": "overgeneralized_rule"}, {"option": "B", "explanation": "Correctly remembers that CS2 is the classic solvent for sulphur, but misses that CS2 also dissolves iodine well (the iodine-in-CS2 violet solution is itself a standard demonstration) — so it can't selectively separate the two.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Assumes ethanoic acid behaves like a generic organic solvent that would dissolve sulphur, when in fact sulphur remains largely insoluble in it too.", "misconceptionId": "overgeneralized_rule"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$A mixture of iodine and sulphur crystals can be separated by treatment with$q$, $q$[{"label": "A", "text": "water to filter off sulphur", "isCorrect": false}, {"label": "B", "text": "carbon (IV) sulphide to filter off iodine", "isCorrect": false}, {"label": "C", "text": "ethanoic acid to filter off sulphur", "isCorrect": false}, {"label": "D", "text": "methanol to filter off iodine", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$Both solids are covalent and largely insoluble in water, so the separation has to come down to a solvent that dissolves one but not the other. Iodine dissolves reasonably well in alcohols like methanol (this is the same chemistry behind tincture of iodine), while elemental sulphur stays essentially insoluble in polar solvents like methanol. So methanol pulls iodine into solution, leaving sulphur behind as the solid residue. Note: carbon (IV) sulphide (CS2) is a well-known solvent for sulphur specifically, but it also dissolves iodine (giving the classic violet CS2/iodine solution), so it isn't selective enough to separate the two — that's the trap in option B.$q$, $q$live$q$, $q$A: Assumes sulphur is water-soluble because it's a familiar 'dissolve it in water' instinct — but elemental sulphur is a nonpolar covalent solid and essentially insoluble in water. B: Correctly remembers that CS2 is the classic solvent for sulphur, but misses that CS2 also dissolves iodine well (the iodine-in-CS2 violet solution is itself a standard demonstration) — so it can't selectively separate the two. C: Assumes ethanoic acid behaves like a generic organic solvent that would dissolve sulphur, when in fact sulphur remains largely insoluble in it too.$q$),
($q$chemistry_0246$q$, $q$Chemistry$q$, $q$Separation of Mixtures$q$, $q$Separation Techniques$q$, $q$Answer a real JAMB 2000 question on Separation Techniques.$q$, $q$[{"conceptId": "kc1jua", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Picks out one absolute size description rather than recognizing sieving depends on a size difference between components, not any particular size range.", "misconceptionId": "misunderstood_terminology"}, {"option": "B", "explanation": "Same error as 'small sizes' — fixates on an absolute size rather than the relative-difference principle sieving actually relies on.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "Gets the logic backwards — if all particles were the same size, a sieve couldn't separate them at all, since none would be selectively held back.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$Sieving is a technique used to separate mixtures containing solid particles of$q$, $q$[{"label": "A", "text": "small sizes", "isCorrect": false}, {"label": "B", "text": "large sizes", "isCorrect": false}, {"label": "C", "text": "different sizes", "isCorrect": true}, {"label": "D", "text": "the same size", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Sieving works purely on particle size — a mesh lets smaller particles through and holds back larger ones. That only separates anything if the particles in the mixture are different sizes to begin with.$q$, $q$live$q$, $q$A: Picks out one absolute size description rather than recognizing sieving depends on a size difference between components, not any particular size range. B: Same error as 'small sizes' — fixates on an absolute size rather than the relative-difference principle sieving actually relies on. D: Gets the logic backwards — if all particles were the same size, a sieve couldn't separate them at all, since none would be selectively held back.$q$),
($q$chemistry_0247$q$, $q$Chemistry$q$, $q$Nature of Matter$q$, $q$Composition of Common Compounds$q$, $q$Answer a real JAMB 2000 question on Composition of Common Compounds.$q$, $q$[{"conceptId": "5s3ecx", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Recognizes Epsom salt as a hydrate (so it has H and O) but overlooks that it's a magnesium sulphate — no aluminium or silicon anywhere in the formula.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Knows limestone is a common mineral but mistakes its composition — it's calcium carbonate, with no aluminium, silicon, or hydrogen present.", "misconceptionId": "memorized_not_understood"}, {"option": "D", "explanation": "Confuses urea's organic composition (C, H, N, O) with an inorganic mineral composition — urea has neither aluminium nor silicon.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$Which of the compounds is composed of Al, Si, O and H?$q$, $q$[{"label": "A", "text": "Epsom salt", "isCorrect": false}, {"label": "B", "text": "Limestone", "isCorrect": false}, {"label": "C", "text": "Clay", "isCorrect": true}, {"label": "D", "text": "Urea", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Clay minerals (like kaolinite, Al2Si2O5(OH)4) are hydrated aluminosilicates — aluminium, silicon, oxygen and hydrogen all appear in the structure. None of the other three come close: Epsom salt is magnesium sulphate heptahydrate (no Al or Si), limestone is calcium trioxocarbonate (IV) (no Al, Si, or H), and urea is an organic nitrogen compound with no Al or Si at all.$q$, $q$live$q$, $q$A: Recognizes Epsom salt as a hydrate (so it has H and O) but overlooks that it's a magnesium sulphate — no aluminium or silicon anywhere in the formula. B: Knows limestone is a common mineral but mistakes its composition — it's calcium carbonate, with no aluminium, silicon, or hydrogen present. D: Confuses urea's organic composition (C, H, N, O) with an inorganic mineral composition — urea has neither aluminium nor silicon.$q$),
($q$chemistry_0248$q$, $q$Chemistry$q$, $q$Chemical Combination$q$, $q$Limiting Reagent$q$, $q$Answer a real JAMB 2000 question on Limiting Reagent.$q$, $q$[{"conceptId": "sam5eu", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Assumes CO is left over because it's the reactant mentioned first in the stem, without actually working the mole ratio against the oxygen available.", "misconceptionId": "guessed_no_reasoning"}, {"option": "B", "explanation": "Confuses the product of the reaction (CO2) with one of the original reactants — CO2 can't be 'in excess' since it's what's being formed, not consumed.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Correctly notices nitrogen is present and unreacted, but nitrogen was never a reactant in this combustion in the first place — it's inert filler in the air, not something that could be 'in excess' relative to a reaction it never took part in.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$50cm3 of carbon (II) oxide was exploded with 150cm3 of air containing 20% oxygen by volume. Which of the reactants was in excess?$q$, $q$[{"label": "A", "text": "Carbon (II) oxide", "isCorrect": false}, {"label": "B", "text": "Carbon (IV) oxide", "isCorrect": false}, {"label": "C", "text": "Oxygen", "isCorrect": true}, {"label": "D", "text": "Nitrogen", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$First find the actual oxygen available: 20% of 150cm3 = 30cm3 O2. The equation 2CO + O2 → 2CO2 needs one volume of O2 for every two volumes of CO, so 50cm3 CO only needs 25cm3 O2. You have 30cm3 available — more than needed — so oxygen is the one left over, in excess.$q$, $q$live$q$, $q$A: Assumes CO is left over because it's the reactant mentioned first in the stem, without actually working the mole ratio against the oxygen available. B: Confuses the product of the reaction (CO2) with one of the original reactants — CO2 can't be 'in excess' since it's what's being formed, not consumed. D: Correctly notices nitrogen is present and unreacted, but nitrogen was never a reactant in this combustion in the first place — it's inert filler in the air, not something that could be 'in excess' relative to a reaction it never took part in.$q$),
($q$chemistry_0249$q$, $q$Chemistry$q$, $q$Oxidation & Reduction$q$, $q$Balancing Half-Equations$q$, $q$Answer a real JAMB 2000 question on Balancing Half-Equations.$q$, $q$[{"conceptId": "d3l5it", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 84, $q$low$q$, $q$moderate$q$, $q$[{"option": "B", "explanation": "A plausible-looking round number that doesn't come from actually balancing the equation — the real coefficient is 14, not 12.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "Another unbalanced guess at the HCl coefficient rather than working through electron/atom balance for the dichromate reduction.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "Likely comes from only balancing the chromium and oxygen atoms while forgetting that HCl also has to supply both the chloride that becomes Cl2 AND the chloride that ends up as KCl and CrCl3.", "misconceptionId": "missing_prerequisite"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$How many moles of HCl will be required to react with potassium heptaoxodichromate (VI) to produce 3 moles of chlorine?$q$, $q$[{"label": "A", "text": "14", "isCorrect": true}, {"label": "B", "text": "12", "isCorrect": false}, {"label": "C", "text": "11", "isCorrect": false}, {"label": "D", "text": "10", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$The standard reaction is K2Cr2O7 + 14HCl → 2KCl + 2CrCl3 + 3Cl2 + 7H2O. Read the coefficients straight off the balanced equation: 14 mol HCl produces exactly 3 mol Cl2, which is precisely the amount asked for — no scaling needed.$q$, $q$live$q$, $q$B: A plausible-looking round number that doesn't come from actually balancing the equation — the real coefficient is 14, not 12. C: Another unbalanced guess at the HCl coefficient rather than working through electron/atom balance for the dichromate reduction. D: Likely comes from only balancing the chromium and oxygen atoms while forgetting that HCl also has to supply both the chloride that becomes Cl2 AND the chloride that ends up as KCl and CrCl3.$q$),
($q$chemistry_0250$q$, $q$Chemistry$q$, $q$Kinetic Theory & Gas Laws$q$, $q$Gas Laws$q$, $q$Answer a real JAMB 2000 question on Gas Laws.$q$, $q$[{"conceptId": "84csd7", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Divides by 2.5 instead of 1.5 — a slip in reading the pressure ratio out of the stem before setting up Boyle's law.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "Multiplies 300 by 1.5 instead of dividing — treats increasing pressure as increasing volume, the inverse relationship flipped the wrong way.", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "Same inverted-relationship error as 450cm3, compounded with an extra scaling mistake.", "misconceptionId": "sign_error"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$The ratio of the initial to the final pressure of a given mass of gas is 1:1.5. Calculate the final volume of the gas if the initial volume was 300cm3 at the same temperature.$q$, $q$[{"label": "A", "text": "120cm3", "isCorrect": false}, {"label": "B", "text": "200cm3", "isCorrect": true}, {"label": "C", "text": "450cm3", "isCorrect": false}, {"label": "D", "text": "750cm3", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Constant temperature means Boyle's law applies: P1V1 = P2V2. Pressure increased by a factor of 1.5, so volume must decrease by the same factor to keep the product constant: V2 = 300 × (1/1.5) = 200cm3.$q$, $q$live$q$, $q$A: Divides by 2.5 instead of 1.5 — a slip in reading the pressure ratio out of the stem before setting up Boyle's law. C: Multiplies 300 by 1.5 instead of dividing — treats increasing pressure as increasing volume, the inverse relationship flipped the wrong way. D: Same inverted-relationship error as 450cm3, compounded with an extra scaling mistake.$q$),
($q$chemistry_0251$q$, $q$Chemistry$q$, $q$Kinetic Theory & Gas Laws$q$, $q$Partial Pressure and Mole Fraction$q$, $q$Answer a real JAMB 2000 question on Partial Pressure and Mole Fraction.$q$, $q$[{"conceptId": "eo9w1a", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Divides the wrong way round (780/452 inverted then misread, or a general ratio-flip) rather than partial pressure over total pressure.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "Off by a factor of 10 from the correct value — a decimal-place slip while dividing 452 by 780.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "A mole fraction greater than 1 is a red flag that shouldn't survive a sanity check — this comes from dividing total pressure by partial pressure instead of the other way round.", "misconceptionId": "formula_recall_error"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$The partial pressure of oxygen in a sample of air is 452mm Hg and the total pressure is 780mm Hg. What is the mole fraction of oxygen?$q$, $q$[{"label": "A", "text": "0.203", "isCorrect": false}, {"label": "B", "text": "0.579", "isCorrect": true}, {"label": "C", "text": "2.030", "isCorrect": false}, {"label": "D", "text": "5.790", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Mole fraction of a gas equals its partial pressure divided by total pressure: 452/780 ≈ 0.579. Mole fractions must always come out between 0 and 1, since they're a fraction of the whole.$q$, $q$live$q$, $q$A: Divides the wrong way round (780/452 inverted then misread, or a general ratio-flip) rather than partial pressure over total pressure. C: Off by a factor of 10 from the correct value — a decimal-place slip while dividing 452 by 780. D: A mole fraction greater than 1 is a red flag that shouldn't survive a sanity check — this comes from dividing total pressure by partial pressure instead of the other way round.$q$),
($q$chemistry_0252$q$, $q$Chemistry$q$, $q$Nature of Matter$q$, $q$States of Matter — Kinetic Theory$q$, $q$Answer a real JAMB 2000 question on States of Matter — Kinetic Theory.$q$, $q$[{"conceptId": "unbitv", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "The particles themselves (atoms/molecules) don't change shape between states — what changes is how they're arranged and how they move relative to each other.", "misconceptionId": "misunderstood_terminology"}, {"option": "B", "explanation": "The number of particles is about quantity of substance, not state — a fixed amount of a substance has the same number of particles whether it's solid, liquid, or gas.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Describes an effect (a gas fills its container, a solid keeps its own shape) rather than the underlying cause — the container shape doesn't define the state, particle movement does.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$The fundamental difference between the three states of matter is the$q$, $q$[{"label": "A", "text": "shape of their particles", "isCorrect": false}, {"label": "B", "text": "number of particles in each state", "isCorrect": false}, {"label": "C", "text": "shape of the container they occupy", "isCorrect": false}, {"label": "D", "text": "degree of movement of their particles", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$Solid, liquid, and gas are distinguished by how free the particles are to move and how much space is between them — tightly locked in place (solid), free to slide past each other (liquid), or moving independently with large gaps (gas). Everything else about the states — density, compressibility, shape — follows from this one difference in particle motion.$q$, $q$live$q$, $q$A: The particles themselves (atoms/molecules) don't change shape between states — what changes is how they're arranged and how they move relative to each other. B: The number of particles is about quantity of substance, not state — a fixed amount of a substance has the same number of particles whether it's solid, liquid, or gas. C: Describes an effect (a gas fills its container, a solid keeps its own shape) rather than the underlying cause — the container shape doesn't define the state, particle movement does.$q$),
($q$chemistry_0253$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Periodic Trends$q$, $q$Answer a real JAMB 2000 question on Periodic Trends.$q$, $q$[{"conceptId": "2oceg6", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Swaps the defining feature of a period with that of a group — same valence electron count is what members of the same group share, not the same period.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Also swaps group and period logic — elements in the same period share the same number of electron shells, not elements in the same group (which gain an extra shell going down).", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Gets the trend backwards — non-metallic character increases across a period as elements move from metals toward non-metals on the right side of the table.", "misconceptionId": "sign_error"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$Which of the following statements is correct about the periodic table?$q$, $q$[{"label": "A", "text": "Elements in the same period have the same number of valence electrons", "isCorrect": false}, {"label": "B", "text": "The valence electrons of the elements in the same period increase progressively across the period", "isCorrect": true}, {"label": "C", "text": "Elements in the same group have the same number of electron shells", "isCorrect": false}, {"label": "D", "text": "The non-metallic properties of the elements tend to decrease across each period", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Moving across a period, each element adds one more electron to the same outer shell — lithium has 1 valence electron, beryllium 2, boron 3, and so on up to neon's 8. That steady increase is exactly what defines a period. It's groups, not periods, that share the same number of valence electrons.$q$, $q$live$q$, $q$A: Swaps the defining feature of a period with that of a group — same valence electron count is what members of the same group share, not the same period. C: Also swaps group and period logic — elements in the same period share the same number of electron shells, not elements in the same group (which gain an extra shell going down). D: Gets the trend backwards — non-metallic character increases across a period as elements move from metals toward non-metals on the right side of the table.$q$),
($q$chemistry_0254$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Metallic Bonding vs. Compound Formation$q$, $q$Answer a real JAMB 2000 question on Metallic Bonding vs. Compound Formation.$q$, $q$[{"conceptId": "z2f3rl", "weight": 1}]$q$::jsonb, 3, $q$analysis$q$, 84, $q$low$q$, $q$light$q$, $q$[{"option": "B", "explanation": "Assumes all bonding types are equivalent in what they produce — but covalent bonding between different elements is exactly how a new compound forms.", "misconceptionId": "overgeneralized_rule"}, {"option": "C", "explanation": "Coordinate bonding still typically links different species together into a new complex or compound, unlike metallic bonding among identical atoms.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Electrovalent (ionic) bonding is the textbook example of combining two different elements into a new substance — it's the opposite of what the question is asking for.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$Which of the following types of bonding does not involve the formation of a new substance?$q$, $q$[{"label": "A", "text": "Metallic", "isCorrect": true}, {"label": "B", "text": "Covalent", "isCorrect": false}, {"label": "C", "text": "Co-ordinate", "isCorrect": false}, {"label": "D", "text": "Electrovalent", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Covalent, coordinate, and electrovalent (ionic) bonding all typically combine different elements into a genuinely new compound. Metallic bonding is different — it's the same metal's atoms held together by delocalized electrons within one element, so nothing new is being formed by combination, just the metal atoms packed and bonded together.$q$, $q$live$q$, $q$B: Assumes all bonding types are equivalent in what they produce — but covalent bonding between different elements is exactly how a new compound forms. C: Coordinate bonding still typically links different species together into a new complex or compound, unlike metallic bonding among identical atoms. D: Electrovalent (ionic) bonding is the textbook example of combining two different elements into a new substance — it's the opposite of what the question is asking for.$q$),
($q$chemistry_0255$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Radioactivity and Half-Life$q$, $q$Answer a real JAMB 2000 question on Radioactivity and Half-Life.$q$, $q$[{"conceptId": "ot0voy", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Confuses half-life (a decay-rate property used for measurement) with nuclear synthesis, which is a completely different process.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Mixes up half-life with nuclear fission — splitting an atom is a deliberate reaction, not something half-life knowledge accomplishes.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Irradiation is exposing something to radiation, which is unrelated to what half-life tells you about a sample.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$The knowledge of half-life can be used to$q$, $q$[{"label": "A", "text": "create an element", "isCorrect": false}, {"label": "B", "text": "detect an element", "isCorrect": true}, {"label": "C", "text": "split an element", "isCorrect": false}, {"label": "D", "text": "irradiate an element", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Half-life is a decay-rate fingerprint — because a radioactive isotope decays at a known, fixed rate, measuring how much of it remains lets you detect its presence or work out how old a sample is (like carbon dating). It's a measurement/identification tool, not a way to physically create, split, or irradiate an element.$q$, $q$live$q$, $q$A: Confuses half-life (a decay-rate property used for measurement) with nuclear synthesis, which is a completely different process. C: Mixes up half-life with nuclear fission — splitting an atom is a deliberate reaction, not something half-life knowledge accomplishes. D: Irradiation is exposing something to radiation, which is unrelated to what half-life tells you about a sample.$q$),
($q$chemistry_0256$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Molecular Shape$q$, $q$Answer a real JAMB 2000 question on Molecular Shape.$q$, $q$[{"conceptId": "cl4iqu", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Swaps CO2 and H2O's shapes — assigns 'bent' to the molecule with no lone pairs (CO2) and 'linear' to the one with two lone pairs (H2O), the reverse of the real pattern.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Shifts all three shapes one position out of order relative to the molecules they belong to.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Reverses the whole sequence — assigns CH4's tetrahedral shape to CO2 and CO2's linear shape to CH4.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$The shape of CO2, H2O and CH4 respectively are$q$, $q$[{"label": "A", "text": "bent, linear and tetrahedral", "isCorrect": false}, {"label": "B", "text": "bent, tetrahedral and linear", "isCorrect": false}, {"label": "C", "text": "linear, bent and tetrahedral", "isCorrect": true}, {"label": "D", "text": "tetrahedral, linear and bent", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Go molecule by molecule: CO2 has no lone pairs on carbon, giving a straight linear shape. H2O has two lone pairs on oxygen, which push the bonds into a bent shape. CH4 has four bonding pairs and no lone pairs, giving the tetrahedral shape. Matching each molecule to its own lone-pair count, one at a time, is safer than trying to memorize the sequence as a block.$q$, $q$live$q$, $q$A: Swaps CO2 and H2O's shapes — assigns 'bent' to the molecule with no lone pairs (CO2) and 'linear' to the one with two lone pairs (H2O), the reverse of the real pattern. B: Shifts all three shapes one position out of order relative to the molecules they belong to. D: Reverses the whole sequence — assigns CH4's tetrahedral shape to CO2 and CO2's linear shape to CH4.$q$),
($q$chemistry_0257$q$, $q$Chemistry$q$, $q$Chemistry & Industry$q$, $q$Welding and Metalworking Flames$q$, $q$Answer a real JAMB 2000 question on Welding and Metalworking Flames.$q$, $q$[{"conceptId": "jv7ln2", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "B", "explanation": "Names a specific metal (brass) rather than the actual welding technique argon is associated with — argon's role is defined by the welding process (arc welding), not the metal being joined.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "Underwater welding is a distinct specialised technique with its own requirements, not the standard association with argon shielding.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Again names a metal rather than a process — steel can be welded by several methods, and this option doesn't capture what makes argon specifically useful.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$The noble gas, argon, is used for$q$, $q$[{"label": "A", "text": "electric arc welding", "isCorrect": true}, {"label": "B", "text": "welding brass", "isCorrect": false}, {"label": "C", "text": "underwater welding", "isCorrect": false}, {"label": "D", "text": "steel welding", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Argon's chemical inertness is exactly why it's used as a shielding gas in arc welding — it blankets the weld to keep atmospheric oxygen and nitrogen from reacting with the hot metal, without reacting itself.$q$, $q$live$q$, $q$B: Names a specific metal (brass) rather than the actual welding technique argon is associated with — argon's role is defined by the welding process (arc welding), not the metal being joined. C: Underwater welding is a distinct specialised technique with its own requirements, not the standard association with argon shielding. D: Again names a metal rather than a process — steel can be welded by several methods, and this option doesn't capture what makes argon specifically useful.$q$),
($q$chemistry_0258$q$, $q$Chemistry$q$, $q$Air and Water$q$, $q$Water Treatment and Hardness$q$, $q$Answer a real JAMB 2000 question on Water Treatment and Hardness.$q$, $q$[{"conceptId": "beypy2", "weight": 1}]$q$::jsonb, 3, $q$recall$q$, 49, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Confuses soft water with hard water — an offensive or 'off' taste is more commonly associated with hard water's dissolved mineral content, not soft water.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Directly contradicts what makes water 'soft' in the first place — soft water is defined by having low calcium content, so calcium precipitating out doesn't fit.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "Introduces a plausible-sounding but unsubstantiated claim — mineral content doesn't have a direct, defining link to bacterial growth in this context.", "misconceptionId": "guessed_no_reasoning"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$A side effect of soft water is that$q$, $q$[{"label": "A", "text": "it gives an offensive taste", "isCorrect": false}, {"label": "B", "text": "excess calcium precipitates", "isCorrect": false}, {"label": "C", "text": "it attacks lead contained in pipes", "isCorrect": true}, {"label": "D", "text": "it encourages the growth of bacteria", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$This is a real, documented water-safety issue: soft water — precisely because it's low in dissolved calcium and magnesium — is more chemically aggressive and can corrode lead plumbing over time, leaching lead into the water supply. Hard water, by contrast, tends to deposit a protective mineral scale inside pipes that actually shields them.$q$, $q$live$q$, $q$A: Confuses soft water with hard water — an offensive or 'off' taste is more commonly associated with hard water's dissolved mineral content, not soft water. B: Directly contradicts what makes water 'soft' in the first place — soft water is defined by having low calcium content, so calcium precipitating out doesn't fit. D: Introduces a plausible-sounding but unsubstantiated claim — mineral content doesn't have a direct, defining link to bacterial growth in this context.$q$),
($q$chemistry_0259$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Coordinate Bonding — Ligands$q$, $q$Answer a real JAMB 2000 question on Coordinate Bonding — Ligands.$q$, $q$[{"conceptId": "25qyuy", "weight": 1}]$q$::jsonb, 3, $q$recall$q$, 49, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Alkaline earth metals can hydrate, but they lack the available d-orbitals that make coordinate (ligand) bonding with water so characteristic of transition metals.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Same gap as alkaline earth metals — alkali metal ions hydrate in solution but don't form the same kind of ligand-based coordination complexes.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Group VII elements are non-metals (halogens) and don't form cationic coordination complexes with water as a ligand in the way transition metal cations do.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$Water molecules can be ligands especially when they are bonded to$q$, $q$[{"label": "A", "text": "alkaline earth metals", "isCorrect": false}, {"label": "B", "text": "alkali metals", "isCorrect": false}, {"label": "C", "text": "transition metals", "isCorrect": true}, {"label": "D", "text": "group VII elements", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Transition metal ions have partially filled d-orbitals that can accept the lone pairs water offers, forming coordination complexes like [Cu(H2O)6]2+ or [Fe(H2O)6]3+ — this is exactly why transition metal salts are so often described and coloured as hydrates. Group 1 and 2 metals and the halogens don't have this same electron-accepting capacity available for coordinate bonding with water.$q$, $q$live$q$, $q$A: Alkaline earth metals can hydrate, but they lack the available d-orbitals that make coordinate (ligand) bonding with water so characteristic of transition metals. B: Same gap as alkaline earth metals — alkali metal ions hydrate in solution but don't form the same kind of ligand-based coordination complexes. D: Group VII elements are non-metals (halogens) and don't form cationic coordination complexes with water as a ligand in the way transition metal cations do.$q$),
($q$chemistry_0260$q$, $q$Chemistry$q$, $q$Environmental Pollution$q$, $q$Natural vs. Synthetic Pollutants$q$, $q$Answer a real JAMB 2000 question on Natural vs. Synthetic Pollutants.$q$, $q$[{"conceptId": "4w8vof", "weight": 1}]$q$::jsonb, 2, $q$analysis$q$, 72, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Overlooks that NO is produced naturally by lightning discharges and by soil bacteria, not only by combustion engines.", "misconceptionId": "missing_prerequisite"}, {"option": "B", "explanation": "Overlooks that CO forms naturally from volcanic activity, wildfires, and other incomplete-combustion processes that don't involve humans at all.", "misconceptionId": "missing_prerequisite"}, {"option": "C", "explanation": "Overlooks that formaldehyde is produced in trace natural amounts by some biological and atmospheric processes, unlike DDT, which has no natural origin whatsoever.", "misconceptionId": "missing_prerequisite"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$The air pollutant unknown in nature is$q$, $q$[{"label": "A", "text": "NO", "isCorrect": false}, {"label": "B", "text": "CO", "isCorrect": false}, {"label": "C", "text": "HCHO", "isCorrect": false}, {"label": "D", "text": "DDT", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$NO forms naturally from lightning and biological processes, CO occurs naturally from incomplete combustion and volcanic activity, and even HCHO (formaldehyde) occurs in small natural amounts. DDT is different — it's a fully synthetic pesticide with no natural source at all, only ever produced by human chemistry.$q$, $q$live$q$, $q$A: Overlooks that NO is produced naturally by lightning discharges and by soil bacteria, not only by combustion engines. B: Overlooks that CO forms naturally from volcanic activity, wildfires, and other incomplete-combustion processes that don't involve humans at all. C: Overlooks that formaldehyde is produced in trace natural amounts by some biological and atmospheric processes, unlike DDT, which has no natural origin whatsoever.$q$),
($q$chemistry_0261$q$, $q$Chemistry$q$, $q$Solubility$q$, $q$Solubility Product Calculations$q$, $q$Answer a real JAMB 2000 question on Solubility Product Calculations.$q$, $q$[{"conceptId": "5cybu4", "weight": 1}]$q$::jsonb, 4, $q$application$q$, 96, $q$medium$q$, $q$moderate$q$, $q$[{"option": "A", "explanation": "Off by two orders of magnitude — likely from a square-rooting error or misplacing the decimal point when taking √(2.0×10-10).", "misconceptionId": "arithmetic_slip"}, {"option": "B", "explanation": "Has the right digits (1.414, correctly recognizing √2 ≈ 1.414) but the wrong power of ten — a decimal-place slip in the exponent.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "Uses the right general size of exponent but the wrong leading digits, likely from an arithmetic error partway through the square root.", "misconceptionId": "arithmetic_slip"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$10dm3 of distilled water is used to wash 2.0 g of a precipitate of AgCl. If the solubility product of AgCl is 2.0 x 10-10 mol2dm-6, what quantity of silver was lost in the process?$q$, $q$[{"label": "A", "text": "2.029 x10-3 mol dm-3", "isCorrect": false}, {"label": "B", "text": "1.414 x 10-3 mol dm-3", "isCorrect": false}, {"label": "C", "text": "2.029 x 10-5 mol dm-3", "isCorrect": false}, {"label": "D", "text": "1.414 x 10-5 mol dm-3", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$AgCl dissolves as Ag+ + Cl-, in a 1:1 ratio, so its solubility 's' satisfies Ksp = [Ag+][Cl-] = s x s = s2. Taking the square root of 2.0×10-10 gives s ≈ 1.414×10-5 mol dm-3 — that's the concentration of silver dissolved into the wash water, which is exactly what's asked for.$q$, $q$live$q$, $q$A: Off by two orders of magnitude — likely from a square-rooting error or misplacing the decimal point when taking √(2.0×10-10). B: Has the right digits (1.414, correctly recognizing √2 ≈ 1.414) but the wrong power of ten — a decimal-place slip in the exponent. C: Uses the right general size of exponent but the wrong leading digits, likely from an arithmetic error partway through the square root.$q$),
($q$chemistry_0262$q$, $q$Chemistry$q$, $q$Energy Changes$q$, $q$Enthalpy of Dissolution$q$, $q$Answer a real JAMB 2000 question on Enthalpy of Dissolution.$q$, $q$[{"conceptId": "fiv6k4", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Gets the direction backwards — hydration releases heat as new attractive bonds form, it doesn't absorb it.", "misconceptionId": "sign_error"}, {"option": "B", "explanation": "Not a meaningful thermodynamic description — 'reduction of heat' isn't the correct term for what happens during hydration.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "Confuses hydration (a chemical/physical process releasing energy) with heat conduction (a physical transfer mechanism) — two unrelated ideas.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$Hydration of ions in solution is associated with$q$, $q$[{"label": "A", "text": "absorption of heat", "isCorrect": false}, {"label": "B", "text": "reduction of heat", "isCorrect": false}, {"label": "C", "text": "conduction of heat", "isCorrect": false}, {"label": "D", "text": "liberation of heat", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$When water molecules surround and attract an ion, new ion-dipole bonds form — and bond formation releases energy. That's why hydration is generally an exothermic process, liberating heat into the surroundings.$q$, $q$live$q$, $q$A: Gets the direction backwards — hydration releases heat as new attractive bonds form, it doesn't absorb it. B: Not a meaningful thermodynamic description — 'reduction of heat' isn't the correct term for what happens during hydration. C: Confuses hydration (a chemical/physical process releasing energy) with heat conduction (a physical transfer mechanism) — two unrelated ideas.$q$),
($q$chemistry_0263$q$, $q$Chemistry$q$, $q$Acids, Bases & Salts$q$, $q$Conjugate Acid-Base Pairs$q$, $q$Answer a real JAMB 2000 question on Conjugate Acid-Base Pairs.$q$, $q$[{"conceptId": "cq46o7", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Mixes up which side of the reaction gains vs. loses a proton — H3O+ (the species that gained a proton) is the conjugate acid, not Cl-.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Labels Cl- as the acid itself, when HCl (before losing its proton) was the acid — Cl- is what's left behind after that proton donation.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "Calls Cl- 'the base' rather than 'the conjugate base' — water is the actual base in this reaction (it accepts the proton), Cl- is only the leftover conjugate species.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$HCl(aq) + H2O(l) → H3O+(aq) + Cl-(aq). In the reaction above, Cl-(aq) is the$q$, $q$[{"label": "A", "text": "Conjugate acid", "isCorrect": false}, {"label": "B", "text": "Acid", "isCorrect": false}, {"label": "C", "text": "Conjugate base", "isCorrect": true}, {"label": "D", "text": "Base", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$HCl is the acid — it donates a proton (H+) to water. Whatever's left after an acid gives up its proton is called its conjugate base. HCl minus H+ is Cl-, so Cl- is HCl's conjugate base.$q$, $q$live$q$, $q$A: Mixes up which side of the reaction gains vs. loses a proton — H3O+ (the species that gained a proton) is the conjugate acid, not Cl-. B: Labels Cl- as the acid itself, when HCl (before losing its proton) was the acid — Cl- is what's left behind after that proton donation. D: Calls Cl- 'the base' rather than 'the conjugate base' — water is the actual base in this reaction (it accepts the proton), Cl- is only the leftover conjugate species.$q$),
($q$chemistry_0264$q$, $q$Chemistry$q$, $q$Acids, Bases & Salts$q$, $q$pH and pOH Calculations$q$, $q$Answer a real JAMB 2000 question on pH and pOH Calculations.$q$, $q$[{"conceptId": "8ocrzy", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 72, $q$low$q$, $q$moderate$q$, $q$[{"option": "A", "explanation": "A rounding or log-calculation slip that lands one unit low — likely from misjudging log(0.25) slightly.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "Suggests pH was taken as roughly 0 (i.e., [H+] treated as close to 1) rather than actually working out -log(0.25).", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "Compounds a similar log-estimation error with an additional small rounding slip.", "misconceptionId": "arithmetic_slip"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$The pOH of a solution of 0.25 mol dm-3 of hydrochloric acid is$q$, $q$[{"label": "A", "text": "12.40", "isCorrect": false}, {"label": "B", "text": "13.40", "isCorrect": true}, {"label": "C", "text": "14.40", "isCorrect": false}, {"label": "D", "text": "14.60", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$HCl is a strong acid, so it dissociates completely: [H+] = 0.25 mol dm-3. pH = -log(0.25) ≈ 0.60. Since pH + pOH = 14 at 25°C, pOH = 14 - 0.60 = 13.40.$q$, $q$live$q$, $q$A: A rounding or log-calculation slip that lands one unit low — likely from misjudging log(0.25) slightly. C: Suggests pH was taken as roughly 0 (i.e., [H+] treated as close to 1) rather than actually working out -log(0.25). D: Compounds a similar log-estimation error with an additional small rounding slip.$q$),
($q$chemistry_0265$q$, $q$Chemistry$q$, $q$Oxidation & Reduction$q$, $q$Balancing Half-Equations$q$, $q$Answer a real JAMB 2000 question on Balancing Half-Equations.$q$, $q$[{"conceptId": "d3l5it", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Confuses this with a different, smaller electron-transfer reaction — manganese here drops all the way from +7 to +2, a five-electron change, not two.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Undercounts the oxidation-state change — Mn goes from +7 (in MnO4-) to +2, a drop of 5, not 3.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "Overcounts the electrons needed — likely confuses the number of oxygen atoms (4, appearing as 4H2O) with the electron count.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$MnO4-(aq) + 8H+(aq) + Y → Mn2+(aq) + 4H2O(l). Y in the equation above represents$q$, $q$[{"label": "A", "text": "2e-", "isCorrect": false}, {"label": "B", "text": "3e-", "isCorrect": false}, {"label": "C", "text": "5e-", "isCorrect": true}, {"label": "D", "text": "7e-", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$This is the standard permanganate reduction half-equation. Balance the charge: the left side has (-1) + 8(+1) = +7 before adding Y; the right side is +2 (from Mn2+). To make both sides equal, Y must contribute -5, which means 5 electrons.$q$, $q$live$q$, $q$A: Confuses this with a different, smaller electron-transfer reaction — manganese here drops all the way from +7 to +2, a five-electron change, not two. B: Undercounts the oxidation-state change — Mn goes from +7 (in MnO4-) to +2, a drop of 5, not 3. D: Overcounts the electrons needed — likely confuses the number of oxygen atoms (4, appearing as 4H2O) with the electron count.$q$),
($q$chemistry_0266$q$, $q$Chemistry$q$, $q$Electrolysis$q$, $q$Faraday's Laws$q$, $q$Answer a real JAMB 2000 question on Faraday's Laws.$q$, $q$[{"conceptId": "cbvosp", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$medium$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Sets up an inverse relationship between mass and charge — but passing more electricity deposits more mass, not less, so charge can't be in the denominator.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "Swaps which quantity is the proportionality constant — Z (electrochemical equivalent) is the constant, not a divisor for Q.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "Introduces an unexplained factor of 2 that doesn't belong in Faraday's basic first-law relationship.", "misconceptionId": "formula_recall_error"}]$q$::jsonb, $q$jamb_past_question$q$, 2000, $q$JAMB$q$, $q$Given that M is the mass of substance deposited in an electrolysis and Q the quantity of electricity consumed, then Faraday's law can be written as$q$, $q$[{"label": "A", "text": "M = Z / Q", "isCorrect": false}, {"label": "B", "text": "M = Q / Z", "isCorrect": false}, {"label": "C", "text": "M = Z / 2Q", "isCorrect": false}, {"label": "D", "text": "M = QZ", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$Faraday's first law says the mass deposited is directly proportional to the charge passed, with the electrochemical equivalent Z as the proportionality constant: M = ZQ (same thing as QZ, multiplication order doesn't matter). Mass should increase as more charge flows — that direct relationship is the whole point of the law.$q$, $q$live$q$, $q$A: Sets up an inverse relationship between mass and charge — but passing more electricity deposits more mass, not less, so charge can't be in the denominator. B: Swaps which quantity is the proportionality constant — Z (electrochemical equivalent) is the constant, not a divisor for Q. C: Introduces an unexplained factor of 2 that doesn't belong in Faraday's basic first-law relationship.$q$);
